"""Validate project structure against expected patterns."""
import os
import sys
import json

def validate_structure(project_root):
    required_dirs = ['src', 'tests', 'docs']
    required_files = ['package.json', 'README.md', 'tsconfig.json']

    issues = []

    for dir_name in required_dirs:
        if not os.path.isdir(os.path.join(project_root, dir_name)):
            issues.append(f"Missing directory: {dir_name}")

    for file_name in required_files:
        if not os.path.isfile(os.path.join(project_root, file_name)):
            issues.append(f"Missing file: {file_name}")

    return {
        'valid': len(issues) == 0,
        'issues': issues
    }

if __name__ == '__main__':
    result = validate_structure(sys.argv[1] if len(sys.argv) > 1 else '.')
    print(json.dumps(result, indent=2))

import { z } from 'zod';
import { db } from '@/lib/db';
