export class {{ENTITY_NAME}}Service {
  async create(data: z.infer<typeof {{ENTITY_NAME}}Schema>) {
    const validated = {{ENTITY_NAME}}Schema.parse(data);
    return db.{{table_name}}.create({ data: validated });
  }

  async getById(id: string) {
    return db.{{table_name}}.findUnique({ where: { id } });
  }

  async update(id: string, data: Partial<z.infer<typeof {{ENTITY_NAME}}Schema>>) {
    return db.{{table_name}}.update({
      where: { id },
      data
    });
