"""Validate API specification against schema."""
import yaml
import json
import sys

def validate_spec(spec_file):
    with open(spec_file) as f:
        spec = yaml.safe_load(f)

    errors = []

    if 'endpoints' not in spec:
        errors.append('Missing required field: endpoints')

    for i, endpoint in enumerate(spec.get('endpoints', [])):
        if 'path' not in endpoint:
            errors.append(f'Endpoint {i}: missing path')
        if 'method' not in endpoint:
            errors.append(f'Endpoint {i}: missing method')

    return {'valid': len(errors) == 0, 'errors': errors}

if __name__ == '__main__':
    result = validate_spec(sys.argv[1])
    print(json.dumps(result, indent=2))
